namespace PZ3D {
 static class SaveDeletionTests {
  static Type Api;static int checks;
  static void Check(bool value,string label){checks++;if(!value)throw new Exception("FAIL: "+label);Console.WriteLine("PASS: "+label);}
  static object Call(string name,params object[] args){try{return Api.GetMethods(BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length&&m.GetParameters().Select((p,i)=>args[i]==null||p.ParameterType.IsInstanceOfType(args[i])).All(ok=>ok)).Invoke(null,args);}catch(TargetInvocationException x){throw x.InnerException;}}
  static System.Collections.Generic.Dictionary<string,object> D(object value){var j=new JavaScriptSerializer();return j.Deserialize<System.Collections.Generic.Dictionary<string,object>>(j.Serialize(value));}
  static Exception Refuses(Action action,string label){Exception failure=null;try{action();}catch(Exception x){failure=x;}Check(failure!=null,label);if(failure!=null)Console.WriteLine("  refused: "+failure.GetType().Name+" "+failure.Message);return failure;}
  static void Put(string path,string value){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,value,new UTF8Encoding(false));}
  sealed class Fixture {
   internal readonly string Root,Path,Marker,Other,Server;internal readonly Engine E;internal readonly string Id;
   internal Fixture(string mode="Survivor"){Root=System.IO.Path.Combine(LauncherTestPaths.Root,"sd-"+Guid.NewGuid().ToString("N").Substring(0,16));E=new Engine(System.IO.Path.Combine(Root,"Game"),System.IO.Path.Combine(Root,"User"),System.IO.Path.Combine(Root,"Data"),true);Id=mode+"/OnlyThis";Path=System.IO.Path.Combine(E.User,"Saves",mode,"OnlyThis");Marker=System.IO.Path.Combine(Path,"map","marker.bin");Other=System.IO.Path.Combine(E.User,"Saves","Survivor","Other","marker.bin");Server=System.IO.Path.Combine(E.User,"Server","settings.ini");Put(E.Config,"{\"vmArgs\":[]}");Put(E.Mods,"VERSION = 1,\nmods\n{\n}\nmaps\n{\n}\n");Put(Marker,"original marker bytes");Put(Other,"other save");Put(Server,"server settings preserved");}
   internal string Stamp(){return (string)D(Call("Preview",E,Id))["stamp"];}
   internal object Delete(string stamp,bool confirmed,Action<string> delete){return Call("Delete",E,Id,stamp,confirmed,delete);}
   internal string Owned(string path){string full=System.IO.Path.GetFullPath(path);if(!full.StartsWith(System.IO.Path.GetFullPath(Root)+System.IO.Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Outside owned save-deletion fixture.");LauncherMaintenance.NoReparse(full);return full;}
   internal void Remove(string path){string full=Owned(path);Check(full==Path,"deleter receives only canonical exact owned save folder");Directory.Delete(full,true);}
   internal void Preserved(){Check(File.ReadAllText(Other)=="other save"&&File.ReadAllText(Server)=="server settings preserved"&&File.ReadAllText(E.Mods)=="VERSION = 1,\nmods\n{\n}\nmaps\n{\n}\n","unrelated save, default mods and server settings preserved");}
  }
  public static int Main(){Console.OutputEncoding=new UTF8Encoding(false);try{Run();Console.WriteLine("SAVE DELETION PASSED: "+checks+" assertions");return 0;}catch(Exception x){Console.WriteLine(x);return 1;}}
  public static void Run(){
   // Break caught: absent service, unchecked folder resolution, or deletion before explicit confirmation.
   Api=typeof(Engine).Assembly.GetType("PZ3D.SaveDeletion");Check(Api!=null,"guarded save deletion API exists");
   var f=new Fixture();var preview=D(Call("Preview",f.E,f.Id));Check((string)preview["id"]=="Survivor/OnlyThis"&&(string)preview["name"]=="OnlyThis"&&(string)preview["mode"]=="Survivor"&&(string)preview["path"]==f.Path,"preview identifies only Saves/mode/name");string stamp=(string)preview["stamp"];
   Refuses(()=>f.Delete(stamp,false,f.Remove),"missing confirmation refuses deletion");Check(File.ReadAllText(f.Marker)=="original marker bytes","cancel preserves marker bytes");f.Preserved();
   // Break caught: stale metadata, missing/added entries, or a failed deleter being reported successful.
   Put(f.Marker,"changed marker contents");Refuses(()=>f.Delete(stamp,true,f.Remove),"changed file invalidates preview");stamp=f.Stamp();Put(System.IO.Path.Combine(f.Path,"new.bin"),"new");Refuses(()=>f.Delete(stamp,true,f.Remove),"added file invalidates preview");stamp=f.Stamp();File.Delete(System.IO.Path.Combine(f.Path,"new.bin"));Refuses(()=>f.Delete(stamp,true,f.Remove),"removed file invalidates preview");
   stamp=f.Stamp();Exception unavailable=Refuses(()=>f.Delete(stamp,true,p=>{throw new IOException("deleter unavailable");}),"deleter exception surfaces");Check(unavailable is IOException&&unavailable.Message=="deleter unavailable"&&File.Exists(f.Marker),"deleter error preserves source without retrying another deletion");
   Exception cancellation=Refuses(()=>f.Delete(stamp,true,p=>{throw new OperationCanceledException("deleter cancelled");}),"deleter cancellation surfaces");Check(cancellation is OperationCanceledException&&File.Exists(f.Marker),"cancellation remains cancellation and preserves source");Refuses(()=>f.Delete(stamp,true,p=>{}),"incomplete deleter cannot report completed");
   var real=new Fixture();real.Owned(real.Path);Call("Delete",real.E,real.Id,real.Stamp(),true);Check(!Directory.Exists(real.Path),"default production boundary permanently deletes the exact owned fixture");real.Preserved();
   foreach(string mode in new[]{"Survivor","Multiplayer"}){var success=new Fixture(mode);var result=D(success.Delete(success.Stamp(),true,success.Remove));Check((string)result["status"]=="completed"&&(string)result["id"]==success.Id&&!Directory.Exists(success.Path),"successful "+mode+" deletion permanently removes exact owned folder");success.Preserved();Refuses(()=>success.Delete((string)preview["stamp"],true,success.Remove),"missing target refuses instead of reporting success");}
   foreach(string id in new[]{"../OnlyThis","Survivor/../OnlyThis","Survivor/OnlyThis/map","Survivor\\OnlyThis","Survivor/OnlyThis.",new string('x',261)})Refuses(()=>Call("Preview",f.E,id),"traversal, nesting or oversized ID refused: "+id.Substring(0,Math.Min(id.Length,40)));
   Guards();MutexWriter();TokenCancellation();Reparse(false);Reparse(true);SnapshotEdges();
  }
  static void TokenCancellation(){
   // Break caught: Cancel arrives during mutex wait but deletion still reaches the deleter.
   Check(Api.GetMethods(BindingFlags.Static|BindingFlags.NonPublic).Any(m=>m.Name=="Delete"&&m.GetParameters().Length==6&&m.GetParameters().Last().ParameterType==typeof(CancellationToken)),"service accepts cancellation through final guarded boundary");var f=new Fixture();string stamp=f.Stamp(),name="Local\\OrangeSaveProfiles-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(System.IO.Path.GetFullPath(System.IO.Path.Combine(f.Path,"mods.txt")).ToUpperInvariant())).ToLowerInvariant();Exception error=null;
   using(var cancel=new CancellationTokenSource())using(var entered=new ManualResetEventSlim())using(var mutex=new Mutex(false,name)){mutex.WaitOne();var deleting=new Thread(()=>{try{entered.Set();Call("Delete",f.E,f.Id,stamp,true,new Action<string>(f.Remove),cancel.Token);}catch(Exception x){error=x;}});try{deleting.Start();Check(entered.Wait(5000)&&SpinWait.SpinUntil(()=>(deleting.ThreadState&ThreadState.WaitSleepJoin)!=0,3000),"deletion waits while writer owns per-save mutex");cancel.Cancel();}finally{mutex.ReleaseMutex();}deleting.Join();Check(error is OperationCanceledException&&File.ReadAllText(f.Marker)=="original marker bytes","cancellation during pending deletion prevents delete and keeps marker bytes");}
  }
  static void SnapshotEdges(){
   // Break caught: root replacement, newly introduced junctions, or empty directory changes reuse consent.
   var f=new Fixture();string stamp=f.Stamp();string moved=f.Owned(f.Path+"-previous");Directory.Move(f.Owned(f.Path),moved);Directory.CreateDirectory(f.Path);Put(f.Marker,"original marker bytes");foreach(string relative in new[]{"map/marker.bin","map",""}){string old=System.IO.Path.Combine(moved,relative),current=System.IO.Path.Combine(f.Path,relative);if(File.Exists(old)){File.SetCreationTimeUtc(current,File.GetCreationTimeUtc(old));File.SetLastWriteTimeUtc(current,File.GetLastWriteTimeUtc(old));}else{Directory.SetCreationTimeUtc(current,Directory.GetCreationTimeUtc(old));Directory.SetLastWriteTimeUtc(current,Directory.GetLastWriteTimeUtc(old));}}Check(File.GetLastWriteTimeUtc(f.Marker)==File.GetLastWriteTimeUtc(System.IO.Path.Combine(moved,"map/marker.bin"))&&Directory.GetCreationTimeUtc(f.Path)==Directory.GetCreationTimeUtc(moved),"replacement fixture preserves metadata independently of file identity");Refuses(()=>f.Delete(stamp,true,f.Remove),"replaced target directory cannot reuse preview even with matching metadata");
   stamp=f.Stamp();Directory.CreateDirectory(System.IO.Path.Combine(f.Path,"empty"));Refuses(()=>f.Delete(stamp,true,f.Remove),"new empty directory invalidates preview");stamp=f.Stamp();Junction(System.IO.Path.Combine(f.Path,"newlink"),moved);Refuses(()=>f.Delete(stamp,true,f.Remove),"junction added after preview refuses before delete");Check(File.Exists(f.Marker),"stale and reparse refusals preserve source");
   var root=new Fixture();string saves=root.Owned(System.IO.Path.Combine(root.E.User,"Saves")),foreign=root.Owned(System.IO.Path.Combine(root.Root,"MovedSaves"));Directory.Move(saves,foreign);Junction(saves,foreign);Refuses(()=>Call("Preview",root.E,root.Id),"Saves root junction refuses without descending");
   var deep=new Engine(f.E.Game,System.IO.Path.Combine(System.IO.Path.GetTempPath(),"ozl-save-depth-"+Guid.NewGuid().ToString("N").Substring(0,8)),f.E.Data,true);string child=System.IO.Path.Combine(deep.User,"Saves","s","n");LauncherMaintenance.NoReparse(deep.User);for(int i=0;i<65;i++)child=System.IO.Path.Combine(child,"d");Directory.CreateDirectory(child);Refuses(()=>Call("Preview",deep,"s/n"),"recursive metadata scan refuses excessive depth");
  }
  static string InterruptProfileWrite(Fixture f,string kind,string id,string slot,string target){
   target=f.Owned(target);byte[] before=File.Exists(target)?File.ReadAllBytes(target):null;
   byte[] after=Encoding.UTF8.GetBytes(slot=="config"?"{\"vmArgs\":[\"-Xmx4g\"]}":"mods\n{\n}\nmaps\n{\n}\n");
   var plan=new PlayProfilePlan{Id=Guid.NewGuid().ToString("N"),Kind=kind,Target=id};plan.Slots.Add(new PlayProfileTransaction.Slot{target=slot,before=before,after=after});Exception interrupted=null;
   try{PlayProfileTransaction.Apply(f.E,plan,()=>false,()=>LauncherMaintenance.CalculateMemoryInfo(16,8),(phase,index)=>{if(phase=="afterWrite")throw new OutOfMemoryException("owned fixture interruption after actual write");},()=>false);}catch(Exception error){interrupted=error;}
   string journal=PlayProfileTransaction.Journal(f.E);if(!(interrupted is OutOfMemoryException))Console.WriteLine("  fixture interruption: "+(interrupted==null?"no interruption":interrupted.ToString()));Check(interrupted is OutOfMemoryException&&File.Exists(journal)&&File.ReadAllBytes(target).SequenceEqual(after),"real profile write fixture leaves an interrupted journal and actual changed target");return journal;
  }
  static string BuddyJournal(Fixture f){return System.IO.Path.Combine(f.E.Data,"backups","buddy-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(System.IO.Path.GetFullPath(f.E.Game).ToUpperInvariant())).Substring(0,24),"pending.json");}
  static void Guards(){
   // Break caught: unrelated recovery records prohibit permanent deletion even
   // though they never write the selected save directory.
   QuietLaunch128Tests.Run();
   foreach(string kind in new[]{"buddy","profile","workshop"}){var f=new Fixture();string journal=kind=="buddy"?BuddyJournal(f):kind=="profile"?PlayProfileTransaction.Journal(f.E):System.IO.Path.Combine(f.E.Data,"workshop-rebuild.pending");Put(journal,"unrelated pending evidence");f.Owned(f.Path);Call("Delete",f.E,f.Id,f.Stamp(),true);Check(!Directory.Exists(f.Path)&&File.ReadAllText(journal)=="unrelated pending evidence",kind+" recovery metadata does not block deletion or get changed");f.Preserved();}
   foreach(bool otherSave in new[]{false,true}){var f=new Fixture();string target=otherSave?System.IO.Path.Combine(f.E.User,"Saves","Survivor","Other","mods.txt"):f.E.Config;string journal=InterruptProfileWrite(f,otherSave?"save":"normal",otherSave?"Survivor/Other":"",otherSave?"saveMods":"config",target),evidence=File.ReadAllText(journal);f.Owned(f.Path);Call("Delete",f.E,f.Id,f.Stamp(),true);Check(!Directory.Exists(f.Path)&&File.ReadAllText(journal)==evidence,otherSave?"another save's interrupted write does not block selected deletion":"normal-profile config recovery does not block selected deletion");f.Preserved();}
   var selected=new Fixture();string mods=System.IO.Path.Combine(selected.Path,"mods.txt"),pending=InterruptProfileWrite(selected,"save",selected.Id,"saveMods",mods),original=File.ReadAllText(pending);Exception conflict=Refuses(()=>Call("Delete",selected.E,selected.Id,selected.Stamp(),true),"only the selected save's actual interrupted saveMods write blocks deletion");Check(conflict is IOException&&conflict.Message.Contains(mods)&&File.Exists(selected.Marker)&&File.ReadAllText(pending)==original,"same-save conflict identifies its exact mods.txt path and preserves save and journal");selected.Preserved();
   foreach(bool profile in new[]{false,true}){var f=new Fixture();string journal;if(profile)journal=InterruptProfileWrite(f,"normal","","config",f.E.Config);else{journal=BuddyJournal(f);Put(journal,"unrelated Buddy recovery");}string evidence=File.ReadAllText(journal);f.Owned(f.Path);using(var controller=new ModernController(f.E.Game,f.E.User,f.E.Data,true)){controller.Execute("saveDelete",new System.Collections.Generic.Dictionary<string,object>{{"id",f.Id},{"stamp",f.Stamp()},{"confirmed",true}});}Check(!Directory.Exists(f.Path)&&File.ReadAllText(journal)==evidence,"public controller permanently deletes with unrelated "+(profile?"normal profile":"Buddy")+" recovery pending");f.Preserved();}
   var unrelated=new Fixture();string fresh=unrelated.Stamp(),launchJournal=System.IO.Path.Combine(unrelated.E.Data,"launch-sessions",LaunchProfiles.Key(unrelated.E)+".json");Directory.CreateDirectory(launchJournal);unrelated.Delete(fresh,true,unrelated.Remove);Check(Directory.Exists(launchJournal)&&!Directory.Exists(unrelated.Path),"unrelated session record is not a deletion prerequisite and remains untouched");
  }
  static void MutexWriter(){
   // Break caught: using a different mutex from SaveProfiles lets a parallel writer race the delete.
   var f=new Fixture();string stamp=f.Stamp();string name="Local\\OrangeSaveProfiles-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(System.IO.Path.GetFullPath(System.IO.Path.Combine(f.Path,"mods.txt")).ToUpperInvariant())).ToLowerInvariant();Exception workerError=null;using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim()){var writer=new Thread(()=>{try{using(var mutex=new Mutex(false,name)){mutex.WaitOne();try{entered.Set();release.Wait();Put(f.Marker,"parallel writer");}finally{mutex.ReleaseMutex();}}}catch(Exception x){workerError=x;entered.Set();}});writer.Start();Check(entered.Wait(5000),"parallel writer owns existing per-save mutex");var timer=new Thread(()=>{Thread.Sleep(150);release.Set();});timer.Start();Refuses(()=>f.Delete(stamp,true,f.Remove),"parallel writer invalidates preview under shared mutex");writer.Join();timer.Join();Check(workerError==null&&File.ReadAllText(f.Marker)=="parallel writer","writer completes and save is preserved");}
  }
  static void Reparse(bool root){
   // Break caught: following a root/nested junction includes or deletes an unrelated directory.
   var f=new Fixture();string target=System.IO.Path.Combine(f.Root,"Foreign"),link=root?System.IO.Path.Combine(f.E.User,"Saves","Survivor","Linked"):System.IO.Path.Combine(f.Path,"linked");Put(System.IO.Path.Combine(target,"marker"),"foreign");Junction(link,target);Refuses(()=>Call("Preview",f.E,root?"Survivor/Linked":f.Id),(root?"root":"nested")+" junction refuses preview without descending");Check(File.ReadAllText(System.IO.Path.Combine(target,"marker"))=="foreign","junction target preserved");
  }
  [System.Runtime.InteropServices.DllImport("kernel32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode,SetLastError=true)]static extern Microsoft.Win32.SafeHandles.SafeFileHandle CreateFile(string path,uint access,uint share,IntPtr security,uint disposition,uint flags,IntPtr template);
  [System.Runtime.InteropServices.DllImport("kernel32.dll",SetLastError=true)]static extern bool DeviceIoControl(Microsoft.Win32.SafeHandles.SafeFileHandle handle,uint code,byte[] input,int length,IntPtr output,int outputLength,out int returned,IntPtr overlap);
  static void Junction(string link,string target){Directory.CreateDirectory(link);byte[] sub=Encoding.Unicode.GetBytes("\\??\\"+target),print=Encoding.Unicode.GetBytes(target);byte[] buffer=new byte[20+sub.Length+print.Length];Array.Copy(BitConverter.GetBytes(0xA0000003U),buffer,4);Array.Copy(BitConverter.GetBytes((ushort)(buffer.Length-8)),0,buffer,4,2);Array.Copy(BitConverter.GetBytes((ushort)sub.Length),0,buffer,10,2);Array.Copy(BitConverter.GetBytes((ushort)(sub.Length+2)),0,buffer,12,2);Array.Copy(BitConverter.GetBytes((ushort)print.Length),0,buffer,14,2);Array.Copy(sub,0,buffer,16,sub.Length);Array.Copy(print,0,buffer,18+sub.Length,print.Length);using(var h=CreateFile(link,0x40000000,3,IntPtr.Zero,3,0x02200000,IntPtr.Zero)){int returned;Check(!h.IsInvalid&&DeviceIoControl(h,0x000900A4,buffer,buffer.Length,IntPtr.Zero,0,out returned,IntPtr.Zero),"isolated no-process junction fixture created");}}
 }
